// src/App.js

import React, { useState, useEffect } from 'react';
import { useTranslation }             from 'react-i18next';
import './index.css';
import './i18n';

import Controls           from './components/Controls';
import LanguageSelector   from './components/LanguageSelector';
import LineChartComponent from './components/LineChartComponent';
import BarChartComponent  from './components/BarChartComponent';

// StatsCan CSV endpoint
const STATCAN_URL =
  'https://www150.statcan.gc.ca/t1/wds/rest/getFullTableDownloadCSV/1810000403/en';
// CORS proxy to avoid browser restrictions during development
const CORS_PROXY = 'https://api.allorigins.win/raw?url=';

function App() {
  const { t } = useTranslation();
  const [rawData, setRawData]                   = useState([]);
  const [provinces, setProvinces]               = useState([]);
  const [foodTypes, setFoodTypes]               = useState([]);
  const [selectedProvinces, setSelectedProvinces] = useState([]);
  const [selectedFoodType, setSelectedFoodType]   = useState('');
  const [dateRange, setDateRange]               = useState({ start: '2020-01', end: '2025-06' });
  const [filteredData, setFilteredData]         = useState([]);
  const [error, setError]                       = useState(null);

  // Fetch & parse the CSV on mount
  useEffect(() => {
    fetch(`${CORS_PROXY}${encodeURIComponent(STATCAN_URL)}`)
      .then(res => {
        if (!res.ok) throw new Error(`Status ${res.status}`);
        return res.text();
      })
      .then(csv => {
        // ← THIS LINE was wrong – now corrected:
        const lines = csv.split('\n').slice(1);

        const data = lines.map(line => {
          const [REF_DATE, GEO, VECTOR, VALUE] = line.split(',');
          return { date: REF_DATE, province: GEO, type: VECTOR, value: +VALUE };
        }).filter(d => d.date && d.province && d.type);

        const provs = [...new Set(data.map(d => d.province))];
        const types = [...new Set(data.map(d => d.type))];

        setRawData(data);
        setProvinces(provs);
        setFoodTypes(types);
        // default to first available so your controls render
        setSelectedProvinces([provs[0]]);
        setSelectedFoodType(types[0]);
      })
      .catch(err => {
        console.error(err);
        setError(err.message);
      });
  }, []);

  // Re-filter when selections change
  useEffect(() => {
    if (!selectedFoodType || selectedProvinces.length === 0) return;
    const fd = rawData.filter(d =>
      selectedProvinces.includes(d.province) &&
      d.type === selectedFoodType &&
      d.date >= dateRange.start &&
      d.date <= dateRange.end
    );
    setFilteredData(fd);
  }, [rawData, selectedProvinces, selectedFoodType, dateRange]);

  // Show fetch error
  if (error) {
    return (
      <div className="app">
        <h1>{t('title')}</h1>
        <p style={{ color: 'red' }}>Error loading data: {error}</p>
      </div>
    );
  }

  // Main render
  return (
    <div className="app">
      <h1>{t('title')}</h1>
      <LanguageSelector />

      <div className="control-panel">
        <Controls
          provinces={provinces}
          selectedProvinces={selectedProvinces}
          onChangeProvinces={setSelectedProvinces}
          foodTypes={foodTypes}
          selectedFoodType={selectedFoodType}
          onChangeFoodType={setSelectedFoodType}
          dateRange={dateRange}
          onChangeDateRange={setDateRange}
        />
      </div>

      <div className="chart-container">
        <LineChartComponent data={filteredData} provinces={selectedProvinces} />
      </div>
      <div className="chart-container">
        <BarChartComponent
          data={filteredData}
          date={dateRange.end}
          provinces={selectedProvinces}
        />
      </div>
    </div>
  );
}

export default App;
